/**
 * stageTemplate — the declarative description of a lamina's stage.
 *
 * A stage is an artwork plus a set of placeholders.  The artwork is static; a
 * placeholder is a rectangle with a pivot and a *binding* saying which model
 * quantity drives it and through which animator.  Nothing here knows it is
 * describing a heart — swap the template and the same renderer draws a
 * different lamina.
 *
 * The template is fetched at runtime rather than imported, so the bindings can
 * be edited without a rebuild.  Geometry is generated by
 * `tools/cut_heart_layers.py`; labels and bindings are hand-written and the
 * tool preserves them.
 */

export type EnvelopeId = 'ventricular' | 'atrial'

/** One additive contribution to a placeholder's scale, gated by a phase window. */
export interface MotionTerm {
  envelope: EnvelopeId
  amount: number
}

/**
 * Scales a motion by a live model quantity.  `reference` is the value at which
 * the gain is 1× — 70 mL of stroke volume leaves the artwork at its drawn size.
 */
export interface Modulator {
  attribute: string
  reference: number
  range: [number, number]
}

export interface Motion {
  animator: string
  terms: MotionTerm[]
  /** null = amplitude is a declared constant, because no model output fits. */
  modulator: Modulator | null
}

export interface Flow {
  animator: string
  rateFrom: string
  colour: string
  particles: number
  radius: number
}

export interface PlaceholderGeometry {
  x: number
  y: number
  w: number
  h: number
  /** Scale pivot: cavity centroid, or vessel root for the great vessels. */
  px: number
  py: number
  /** Great vessels only: centreline from the root outward. */
  path?: [number, number][]
}

export interface Placeholder {
  label: string
  asset: string
  geometry: PlaceholderGeometry
  motion?: Motion
  flow?: Flow
}

export interface StageTemplate {
  laminaId: string
  artwork: { src: string; width: number; height: number }
  /**
   * Where beat timing comes from.  `bind: "HR"` is a raw sensor — the stage
   * surfaces that as a violation rather than hiding it, because the model does
   * not yet emit a rhythm outcome.
   */
  rhythm: {
    bind: string
    envelopes: Record<EnvelopeId, [number, number]>
  }
  /** Painter's order — later entries draw on top. */
  drawOrder: string[]
  placeholders: Record<string, Placeholder>
}

/** Where a bound quantity came from, which is what Lee's rule is about. */
export type Provenance = 'model' | 'sensor' | 'constant' | 'missing'

export interface BindingRow {
  channel: 'timing' | 'amplitude' | 'flow'
  attribute: string | null
  provenance: Provenance
  /**
   * Owned by the stage rather than the placeholder.  Beat timing is one
   * binding that every placeholder reads, so it is reported once at stage
   * level instead of turning all six frames the same colour.
   */
  shared?: boolean
}

export function provenanceOf(attribute: string, sources: Record<string, string>): Provenance {
  const s = sources[attribute]
  if (s === 'PRELIMINARY') return 'model'
  if (s === 'SENSOR') return 'sensor'
  return 'missing'
}

/** The stage-wide beat binding. */
export function describeRhythm(
  template: StageTemplate,
  sources: Record<string, string>
): BindingRow {
  return {
    channel: 'timing',
    attribute: template.rhythm.bind,
    provenance: provenanceOf(template.rhythm.bind, sources),
    shared: true,
  }
}

/**
 * Describe every channel of one placeholder: what drives it and whether that
 * source is allowed to. `sources` comes from the lamina schema, so this is the
 * model's own classification rather than a second opinion held by the UI.
 */
export function describeBindings(
  place: Placeholder,
  template: StageTemplate,
  sources: Record<string, string>
): BindingRow[] {
  const rows: BindingRow[] = []
  if (place.motion) {
    rows.push(describeRhythm(template, sources))
    const mod = place.motion.modulator
    rows.push({
      channel: 'amplitude',
      attribute: mod?.attribute ?? null,
      provenance: mod ? provenanceOf(mod.attribute, sources) : 'constant',
    })
  }
  if (place.flow) {
    rows.push({
      channel: 'flow',
      attribute: place.flow.rateFrom,
      provenance: provenanceOf(place.flow.rateFrom, sources),
    })
  }
  return rows
}

/** Resolved template plus the base URL its assets are relative to. */
export interface LoadedStage {
  template: StageTemplate
  assetUrl: (file: string) => string
}

export async function loadStage(dir: string): Promise<LoadedStage> {
  const base = `${import.meta.env.BASE_URL}${dir}/`
  const res = await fetch(`${base}template.json`)
  if (!res.ok) throw new Error(`stage template ${dir}: ${res.status}`)
  return { template: await res.json(), assetUrl: (file) => `${base}${file}` }
}

/** Point at fraction `u` ∈ [0,1] along a polyline, linearly interpolated. */
export function alongPath(path: [number, number][], u: number): [number, number] {
  const t = Math.min(0.9999, Math.max(0, u)) * (path.length - 1)
  const i = Math.floor(t)
  const f = t - i
  const a = path[i]
  const b = path[i + 1] ?? a
  return [a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f]
}
